def cal_electbill(units):
    # Assuming the electricity rates are as follows:
    # First 50 units: Rs. 8 per unit
    # Next 100 units: Rs. 10 per unit
    # Beyond 150 units: Rs. 12 per unit

    if units <= 50:
        total_bill = units * 8
    elif units <= 150:
        total_bill = (50 * 8) + ((units - 50) * 10)
    else:
        total_bill = (50 * 8) + (100 * 10) + ((units - 150) * 12)

    # Adding a fixed charge of Rs. 50 for maintenance and service
    total_bill += 50

    # Rounding the bill to two decimal places for currency formatting
    return round(total_bill, 2)

